<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');if($_SERVER['REQUEST_METHOD']==='POST'){$q=$db->prepare('INSERT INTO client_success_profiles(client_id,health,satisfaction_score,renewal_date,renewal_value,success_owner_id,risk_notes,goals,last_reviewed_at) VALUES(?,?,?,?,?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE health=VALUES(health),satisfaction_score=VALUES(satisfaction_score),renewal_date=VALUES(renewal_date),renewal_value=VALUES(renewal_value),success_owner_id=VALUES(success_owner_id),risk_notes=VALUES(risk_notes),goals=VALUES(goals),last_reviewed_at=NOW()');$q->execute([(int)$_POST['client_id'],$_POST['health'],$_POST['satisfaction_score']?:null,$_POST['renewal_date']?:null,$_POST['renewal_value']?:null,$_POST['success_owner_id']?:null,trim($_POST['risk_notes']??''),trim($_POST['goals']??'')]);header('Location: client-success.php');exit;}$rows=$db->query('SELECT p.*,c.name client_name,CONCAT(s.first_name," ",s.last_name) owner_name FROM client_success_profiles p JOIN clients c ON c.id=p.client_id LEFT JOIN staff_members s ON s.id=p.success_owner_id ORDER BY FIELD(p.health,"critical","at_risk","healthy"),p.renewal_date')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Client Success</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><h1 class="h3">Client Success</h1><div class="card mb-4"><div class="card-body"><form method="post" class="row g-2"><div class="col-md-2"><input class="form-control" type="number" name="client_id" placeholder="Client ID" required></div><div class="col-md-2"><select class="form-select" name="health"><option>healthy</option><option>at_risk</option><option>critical</option></select></div><div class="col-md-2"><input class="form-control" type="number" step="0.01" min="0" max="100" name="satisfaction_score" placeholder="CSAT"></div><div class="col-md-2"><input class="form-control" type="date" name="renewal_date"></div><div class="col-md-2"><input class="form-control" type="number" step="0.01" name="renewal_value" placeholder="Renewal value"></div><div class="col-md-2"><input class="form-control" type="number" name="success_owner_id" placeholder="Owner ID"></div><div class="col-md-6"><textarea class="form-control" name="goals" placeholder="Client goals"></textarea></div><div class="col-md-6"><textarea class="form-control" name="risk_notes" placeholder="Risk notes"></textarea></div><div class="col-12"><button class="btn btn-dark">Save Success Profile</button></div></form></div></div><div class="card"><div class="card-body"><table class="table"><thead><tr><th>Client</th><th>Health</th><th>CSAT</th><th>Renewal</th><th>Owner</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$e($r['client_name'])?></td><td><?=$e($r['health'])?></td><td><?=$e($r['satisfaction_score'])?></td><td><?=$e($r['renewal_date'])?> / <?=$e($r['renewal_value'])?></td><td><?=$e($r['owner_name'])?></td></tr><?php endforeach;?></tbody></table></div></div></main></body></html>